package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.Bitmap;import android.os.*;import android.view.*;import android.widget.*;import androidx.media3.common.*;import androidx.media3.session.*;import androidx.media3.session.MediaController;import androidx.media3.exoplayer.source.DefaultMediaSourceFactory;import com.google.common.util.concurrent.ListenableFuture;import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;import org.json.JSONObject;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class RadioPlaybackTest {
 private interface Check{boolean ready();}
 private void waitFor(Check check)throws Exception{for(int i=0;i<300;i++){boolean[] r={false};getInstrumentation().runOnMainSync(()->r[0]=check.ready());if(r[0])return;Thread.sleep(50);}fail("Radio scenario timed out");}
 private void shell(String command)throws Exception{try(InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(getInstrumentation().getUiAutomation().executeShellCommand(command))){byte[] b=new byte[256];while(in.read(b)!=-1){}}}
 private View find(View root,String description){if(android.text.TextUtils.equals(description,root.getContentDescription()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=find(((ViewGroup)root).getChildAt(i),description);if(found!=null)return found;}return null;}
 @Test public void httpsStationPlaysInsideOndaInBackgroundAndPauseStopsStream()throws Exception{
  Instrumentation ins=getInstrumentation();Context c=ins.getTargetContext();SharedPreferences prefs=c.getSharedPreferences("radio",0),speech=c.getSharedPreferences("speech_audio",0);Map<String,String> old=new HashMap<>();for(String key:new String[]{"catalog","favorites","query"})old.put(key,prefs.getString(key,null));boolean hadCountry=prefs.contains("brazil"),oldCountry=prefs.getBoolean("brazil",true),hadQuiet=speech.contains("quiet"),hadEconomy=prefs.contains(RadioData.KEY),oldEconomy=prefs.getBoolean(RadioData.KEY,true);int oldQuiet=SpeechSettings.quiet(c);Set<String> localFavorites=new HashSet<>(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()));
  RadioStation station=new RadioStation("native-radio-fixture","Rádio de teste","https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/main/Onda/tests/fixtures/radio-tone.wav","Teste","PCM",0,false);RadioStore.cache(c,Collections.singletonList(station),"",true);prefs.edit().putString("favorites","[]").putBoolean(RadioData.KEY,true).commit();ListenableFuture<MediaController>[] connect=new ListenableFuture[1];ins.runOnMainSync(()->connect[0]=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());MediaController player=connect[0].get(15,TimeUnit.SECONDS);PlaybackParameters[] originalSpeed={null};Activity[] screen={null};ListenableFuture<SessionResult>[] command=new ListenableFuture[1];
  try{boolean hls=false;for(int type:new DefaultMediaSourceFactory(c).getSupportedTypes())if(type==C.CONTENT_TYPE_HLS)hls=true;assertTrue("HLS radio module missing",hls);ins.runOnMainSync(()->{originalSpeed[0]=player.getPlaybackParameters();player.pause();player.clearMediaItems();player.setPlaybackParameters(new PlaybackParameters(1.5f,1f));player.setShuffleModeEnabled(false);player.setRepeatMode(Player.REPEAT_MODE_OFF);SpeechSettings.quiet(c,2);command[0]=player.sendCustomCommand(new SessionCommand(SpeechSettings.COMMAND,Bundle.EMPTY),Bundle.EMPTY);});assertEquals(SessionResult.RESULT_SUCCESS,command[0].get(5,TimeUnit.SECONDS).resultCode);
   screen[0]=ins.startActivitySync(new Intent(c,RadioActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();waitFor(()->find(screen[0].findViewById(android.R.id.content),"Ouvir rádio Rádio de teste")!=null);ins.runOnMainSync(()->{assertFalse(player.getPlayWhenReady());find(screen[0].findViewById(android.R.id.content),"Ouvir rádio Rádio de teste").performClick();});waitFor(()->player.isPlaying()&&player.getCurrentPosition()>600);ins.runOnMainSync(()->{assertEquals("radio:"+station.id,player.getCurrentMediaItem().mediaId);assertEquals(RadioData.ADAPTIVE_MAX,player.getTrackSelectionParameters().maxAudioBitrate);assertTrue(player.getTrackSelectionParameters().forceLowestBitrate);assertEquals(1f,player.getPlaybackParameters().speed,.001f);find(screen[0].findViewById(android.R.id.content),"Favoritar rádio Rádio de teste").performClick();assertTrue(RadioStore.favorite(c,station.id));command[0]=player.sendCustomCommand(new SessionCommand(SpeechSettings.STATUS,Bundle.EMPTY),Bundle.EMPTY);});assertTrue("The radio must feed decoded audio through the same engine",command[0].get(5,TimeUnit.SECONDS).extras.getLong("quiet_frames")>0);
   Bitmap capture=ins.getUiAutomation().takeScreenshot();if(capture!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"radio-player.png"))){capture.compress(Bitmap.CompressFormat.PNG,100,out);capture.recycle();}
   long[] position={0};ins.runOnMainSync(()->position[0]=player.getCurrentPosition());assertTrue(ins.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME));Thread.sleep(900);ins.runOnMainSync(()->{assertTrue(player.isPlaying());assertTrue(player.getCurrentPosition()>position[0]+300);position[0]=player.getCurrentPosition();});shell("input keyevent 223");Thread.sleep(800);ins.runOnMainSync(()->{assertTrue(player.isPlaying());assertTrue(player.getCurrentPosition()>position[0]+300);player.pause();});shell("input keyevent 224");shell("wm dismiss-keyguard");waitFor(()->player.getPlaybackState()==Player.STATE_IDLE&&!player.getPlayWhenReady());
   Activity radio=screen[0];screen[0]=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();waitFor(()->find(screen[0].findViewById(android.R.id.content),"Remover dos favoritos")!=null);ins.runOnMainSync(()->{View root=screen[0].findViewById(android.R.id.content);assertFalse(find(root,"Posição na música").isEnabled());find(root,"Remover dos favoritos").performClick();assertFalse(RadioStore.favorite(c,station.id));assertEquals(localFavorites,c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()));radio.finish();player.clearMediaItems();});waitFor(()->Math.abs(player.getPlaybackParameters().speed-1.5f)<.001f);ins.runOnMainSync(()->{assertEquals(Integer.MAX_VALUE,player.getTrackSelectionParameters().maxAudioBitrate);assertFalse(player.getTrackSelectionParameters().forceLowestBitrate);});
   JSONObject report=new JSONObject().put("httpsAudioDecoded",true).put("sameAudioEngineAndQuietEnhancement",true).put("continuesInBackground",true).put("continuesWithScreenOff",true).put("pauseReleasesStream",true).put("radioFavoritesSharedWithMainPlayer",true).put("localFavoritesUnchanged",true).put("localPlaybackSpeedRestored",true).put("hlsModuleAvailable",true).put("radioEconomyAdaptiveCap",64000).put("lowestRadioBitratePreferred",true).put("localAudioQualityRestored",true);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"radio-playback.json"))){out.write(report.toString(2).getBytes("UTF-8"));}
  }finally{shell("input keyevent 224");shell("wm dismiss-keyguard");ins.runOnMainSync(()->{player.pause();player.clearMediaItems();if(originalSpeed[0]!=null)player.setPlaybackParameters(originalSpeed[0]);SpeechSettings.quiet(c,oldQuiet);player.sendCustomCommand(new SessionCommand(SpeechSettings.COMMAND,Bundle.EMPTY),Bundle.EMPTY);if(screen[0]!=null)screen[0].finish();MediaController.releaseFuture(connect[0]);});SharedPreferences.Editor e=prefs.edit();for(Map.Entry<String,String> entry:old.entrySet())if(entry.getValue()==null)e.remove(entry.getKey());else e.putString(entry.getKey(),entry.getValue());if(hadEconomy)e.putBoolean(RadioData.KEY,oldEconomy);else e.remove(RadioData.KEY);if(hadCountry)e.putBoolean("brazil",oldCountry);else e.remove("brazil");e.commit();e=speech.edit();if(hadQuiet)e.putInt("quiet",oldQuiet);else e.remove("quiet");e.commit();}
 }
}
